CREATE OR REPLACE FUNCTION public.get_user_role(user_uuid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    user_role TEXT;
BEGIN
    SELECT role INTO user_role 
    FROM public.user_roles 
    WHERE user_roles.user_id = get_user_role.user_uuid;
    
    RETURN COALESCE(user_role, 'merchant');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_role_secure(user_uuid uuid)
 RETURNS user_role_enum
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    user_role user_role_enum;
BEGIN
    SELECT role INTO user_role 
    FROM public.user_roles 
    WHERE user_roles.user_id = get_user_role_secure.user_uuid;
    
    RETURN COALESCE(user_role, 'merchant'::user_role_enum);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.is_user_banned(user_uuid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    banned_until TIMESTAMP WITH TIME ZONE;
BEGIN
    SELECT user_roles.banned_until INTO banned_until
    FROM public.user_roles
    WHERE user_roles.user_id = is_user_banned.user_uuid;
    
    RETURN COALESCE(banned_until > NOW(), false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.log_audit_event(p_user_id uuid, p_action text, p_target_type text DEFAULT NULL::text, p_target_id text DEFAULT NULL::text, p_details jsonb DEFAULT NULL::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    audit_id BIGINT;
    user_email TEXT;
    request_headers JSONB;
BEGIN
    -- Get user email from auth.users
    SELECT email INTO user_email
    FROM auth.users
    WHERE id = p_user_id;
    
    -- Try to get headers from current_setting
    BEGIN
        request_headers := current_setting('request.headers', true)::jsonb;
    EXCEPTION
        WHEN OTHERS THEN
            request_headers := '{}'::jsonb;
    END;
    
    -- Insert audit record
    INSERT INTO public.audit_logs (
        user_id,
        user_email,
        action,
        target_type,
        target_id,
        details,
        ip_address,
        user_agent
    ) VALUES (
        p_user_id,
        user_email,
        p_action,
        p_target_type,
        p_target_id,
        p_details,
        inet_client_addr(),
        COALESCE(request_headers->>'user-agent', '')
    ) RETURNING id INTO audit_id;
    
    RETURN audit_id;
EXCEPTION
    WHEN OTHERS THEN
        -- Log the error but don't fail the operation
        RAISE WARNING 'Failed to log audit event: %', SQLERRM;
        RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.migrate_users_to_auth()
 RETURNS TABLE(success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    migrated_count INTEGER := 0;
    user_record RECORD;
    auth_user_id UUID;
BEGIN
    -- Only proceed if users table has data
    IF NOT EXISTS (SELECT 1 FROM public.users LIMIT 1) THEN
        RETURN QUERY SELECT true, 'No users to migrate'::TEXT;
        RETURN;
    END IF;
    
    -- Migrate each user
    FOR user_record IN SELECT * FROM public.users LOOP
        -- Create auth user
        INSERT INTO auth.users (
            id,
            email,
            created_at,
            updated_at
        ) VALUES (
            gen_random_uuid(),
            user_record.email,
            COALESCE(user_record.created_at, NOW()),
            COALESCE(user_record.updated_at, NOW())
        ) ON CONFLICT (email) DO NOTHING
        RETURNING id INTO auth_user_id;
        
        -- Get the user ID if already exists
        IF auth_user_id IS NULL THEN
            SELECT id INTO auth_user_id 
            FROM auth.users 
            WHERE email = user_record.email;
        END IF;
        
        -- Insert into user_roles
        INSERT INTO public.user_roles (user_id, role) 
        VALUES (auth_user_id, user_record.role::user_role_enum)
        ON CONFLICT (user_id) DO UPDATE
        SET role = EXCLUDED.role;
        
        migrated_count := migrated_count + 1;
    END LOOP;
    
    RETURN QUERY SELECT true, format('Migrated %s users', migrated_count)::TEXT;
END;
$function$
;

