create policy "Admins can view all link clicks"
on "public"."link_clicks"
as permissive
for select
to public
using ((EXISTS ( SELECT 1
   FROM user_roles
  WHERE ((user_roles.user_id = auth.uid()) AND (user_roles.role = ANY (ARRAY['admin'::user_role_enum, 'superadmin'::user_role_enum]))))));


create policy "Merchants can view own link clicks"
on "public"."link_clicks"
as permissive
for select
to public
using ((EXISTS ( SELECT 1
   FROM merchants
  WHERE ((merchants.id = link_clicks.merchant_id) AND (merchants.auth_user_id = auth.uid())))));


create policy "Public can insert link clicks"
on "public"."link_clicks"
as permissive
for insert
to public
with check (true);


